import numpy as np

def jacobi_symbol(a, n):
    """Compute Jacobi symbol (a/n)"""
    if n <= 0 or n % 2 == 0:
        return 0
    a = a % n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 in [3, 5]:
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a = a % n
    return result if n == 1 else 0

def modular_distance(r, s, mod=30):
    """Minimum distance between r and s modulo mod"""
    diff = abs(r - s)
    return min(diff, mod - diff)

def gap_weight(r, s, mod=30):
    """Inverse modular distance weight"""
    dist = modular_distance(r, s, mod)
    return 1.0 / max(dist, 1)

