import numpy as np

def circular_distance(r1, r2, mod=30):
    """Compute circular distance between residues"""
    diff = abs(r2 - r1)
    return min(diff, mod - diff)

def analyze_transition_biases():
    # Generate first 50000 primes for speed
    primes = generate_primes(611953)  # 50000th prime

    # Valid residue classes mod 30
    residues = [1, 7, 11, 13, 17, 19, 23, 29]

    # Count transitions
    transitions = {}
    for r1 in residues:
        for r2 in residues:
            transitions[(r1, r2)] = 0

    # Count consecutive prime transitions
    for i in range(len(primes) - 1):
        r1 = primes[i] % 30
        r2 = primes[i + 1] % 30
        if r1 in residues and r2 in residues:
            transitions[(r1, r2)] += 1

    # Calculate biases
    biases = {}
    distances = {}

    for r1 in residues:
        total_from_r1 = sum(transitions[(r1, r2)] for r2 in residues)
        for r2 in residues:
            if total_from_r1 > 0:
                observed_prob = transitions[(r1, r2)] / total_from_r1
                bias = observed_prob - 1/8  # Expected uniform probability
                biases[(r1, r2)] = abs(bias)
                distances[(r1, r2)] = circular_distance(r1, r2)

    # Extract non-zero biases and corresponding distances
    valid_pairs = [(r1, r2) for (r1, r2) in biases.keys() 
                   if biases[(r1, r2)] > 1e-6 and distances[(r1, r2)] > 0]

    if len(valid_pairs) < 10:
        print("VERDICT: FALSIFIED - Insufficient valid data points")
        return

    log_biases = [np.log(biases[pair]) for pair in valid_pairs]
    log_distances = [np.log(distances[pair]) for pair in valid_pairs]

    # Calculate correlation coefficient
    correlation = np.corrcoef(log_biases, log_distances)[0, 1]

    # Print detailed analysis
    print(f"Number of valid transition pairs: {len(valid_pairs)}")
    print(f"Correlation between log|bias| and log(distance): {correlation:.4f}")

    # Show some examples
    print("\nTop 5 transitions by bias magnitude:")
    sorted_pairs = sorted(valid_pairs, key=lambda p: biases[p], reverse=True)[:5]
    for pair in sorted_pairs:
        r1, r2 = pair
        print(f"({r1},{r2}): bias={biases[pair]:.6f}, distance={distances[pair]}")

    # Test hypothesis
    if correlation < -0.6:
        print(f"\nVERDICT: SUPPORTED - Correlation {correlation:.4f} < -0.6")
    else:
        print(f"\nVERDICT: FALSIFIED - Correlation {correlation:.4f} >= -0.6")

